<script setup>
import {computed,nextTick,ref} from 'vue';
import BattleActionIcon from './battle/BattleActionIcon.vue';
import BattleActionArtwork from './battle/BattleActionArtwork.vue';
import screens from '../data/battle-guide-screens.json';
import {battleTours,guideActions,guideRules} from '../data/battleGuide.js';
const mode=ref('player'),point=ref('status'),action=ref('summon'),example=ref(0);
const explanation=ref(null);
const tour=computed(()=>battleTours[mode.value]),screen=computed(()=>screens[tour.value.screenshot]),selected=computed(()=>tour.value.points.find(p=>p.id===point.value)??tour.value.points[0]);
const selectedIndex=computed(()=>tour.value.points.findIndex(p=>p.id===selected.value.id));
const chosenAction=computed(()=>guideActions.find(item=>item.id===action.value));
const enlarged=ref(null);
const actionName=id=>id==='end'?'end_turn':id==='inspect'?'info':id==='switch'?'more':id;
const exampleSteps=[
 {label:'Mulai',badge:'3 AP',ap:3,text:'Contoh giliran dengan 3 AP dan slot Active kosong. Biaya Summon dan Serang masing-masing 1 AP pada contoh ini.'},
 {label:'Summon',badge:'−1 AP',ap:2,text:'Scan satu kartu Base terdaftar ke Active. Biaya 1 AP, tersisa 2 AP. Kartu Base boleh menyerang pada giliran saat dipanggil.'},
 {label:'Serang',badge:'−1 AP',ap:1,text:'Pilih kartu tadi, tekan Serang, pilih target lawan, lalu konfirmasi. Tersisa 1 AP. Kartu yang menyerang tetap di Active sampai giliranmu berikutnya; tidak bisa langsung ke Bench.'},
 {label:'Akhiri giliran',badge:'0 AP biaya',ap:0,text:'Tidak wajib menghabiskan AP. Akhiri giliran dan konfirmasi: 1 AP yang tersisa dilepas, bukan biaya tambahan. Kartu penyerang tetap di Active dan lawan mendapat kesempatan membalas. Di giliran lain, sisa AP bisa dipakai untuk bantuan dari kartu yang memenuhi syarat.'},
];
function changeMode(value){mode.value=value;point.value=battleTours[value].points[0].id;}
async function selectPoint(value){
 point.value=value;
 if(window.matchMedia('(max-width: 1050px)').matches){
  await nextTick();
  explanation.value?.scrollIntoView({block:'start',behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});
 }
}
async function tabKey(event){
 if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();changeMode(event.key==='Home'?'player':event.key==='End'?'public':mode.value==='player'?'public':'player');await nextTick();document.getElementById(`guide-tab-${mode.value}`)?.focus();
}
function step(direction){point.value=tour.value.points[Math.max(0,Math.min(tour.value.points.length-1,selectedIndex.value+direction))].id;}
</script>
<template>
 <section id="panduan" class="battle-guide" aria-labelledby="battle-guide-title">
  <header class="battle-guide-heading"><span class="guide-eyebrow">PANDUAN PERMAINAN · TCG V1</span><h2 id="battle-guide-title">Kenali layar.<br>Mulai langkah pertamamu.</h2><p>Belum pernah bermain? Klik lingkaran pada gambar untuk mengenali menunya, lalu ikuti contoh giliran di bawah.</p></header>
  <ol class="guide-start"><li><b>Siapkan kartu</b><span>Minta bantuan penyelenggara untuk deck, UID terdaftar, dan jumlah kartu awal sesuai Game Setup.</span></li><li><b>Masuk sebagai pemain</b><span>Gunakan kode pemain dari penyelenggara. Scan kartu awal ke Active dan tunggu kedua pemain siap.</span></li><li><b>Ikuti giliran</b><span>Saat GILIRANMU, periksa AP dan timer. Pilih kartu, jalankan aksi, lalu akhiri giliran.</span></li></ol>
  <div class="guide-tour-tabs" role="tablist" aria-label="Pilih layar panduan" @keydown="tabKey"><button v-for="[key,value] in Object.entries(battleTours)" :id="`guide-tab-${key}`" :key="key" type="button" role="tab" :aria-selected="mode===key" :tabindex="mode===key?0:-1" aria-controls="guide-tour-panel" @click="changeMode(key)">{{ value.label }}<span>{{ key==='player'?'Untuk yang bermain':'Untuk yang menonton' }}</span></button></div>
  <div id="guide-tour-panel" class="guide-tour" role="tabpanel" :aria-labelledby="`guide-tab-${mode}`">
   <div class="guide-visual"><div class="guide-image"><img :src="screen.src" :width="screen.width" :height="screen.height" :alt="`Contoh layar ${tour.label} dengan penanda menu yang bisa dipilih`" loading="lazy"/><button v-for="(item,index) in tour.points" :key="`${mode}-${item.id}`" type="button" class="guide-pin" :class="{selected:selected.id===item.id}" :style="{left:`${screen.points[item.id].x}%`,top:`${screen.points[item.id].y}%`}" :aria-label="`${index+1}. ${item.title}`" :aria-pressed="selected.id===item.id" @click="selectPoint(item.id)">{{ index+1 }}</button></div><p class="guide-caption">{{ tour.caption }} Gambar terbaru memakai data demo. Posisi panel dapat berbeda pada HP atau layout publik lain.</p><button type="button" class="guide-enlarge" @click="enlarged.showModal()">⤢ Perbesar layar {{ tour.label }}</button></div>
   <aside ref="explanation" class="guide-explanation" aria-live="polite" aria-atomic="true"><span class="guide-point-count">MENU {{ selectedIndex+1 }} / {{ tour.points.length }}</span><h3>{{ selected.title }}</h3><p>{{ selected.text }}</p><div class="guide-tip"><b>Ingat</b><p>{{ selected.tip }}</p></div><div class="guide-step-buttons"><button type="button" :disabled="selectedIndex===0" @click="step(-1)">← Sebelumnya</button><button type="button" :disabled="selectedIndex===tour.points.length-1" @click="step(1)">Berikutnya →</button></div></aside>
   <nav class="guide-menu-list" aria-label="Daftar menu pada gambar"><button v-for="(item,index) in tour.points" :key="item.id" type="button" :aria-pressed="selected.id===item.id" @click="selectPoint(item.id)"><b>{{ index+1 }}</b>{{ item.title }}</button></nav>
  </div>
  <section class="guide-action-section" aria-labelledby="guide-action-title"><div class="guide-section-heading"><span class="guide-eyebrow">PILIH AKSI</span><h3 id="guide-action-title">Tombol ini untuk apa?</h3><p>Biaya di bawah adalah contoh default. Ikuti biaya dan syarat yang tampil pada battle-mu. Combo, Fusion, Ultimate, Pulihkan HP, dan Synergy dibuka melalui Aksi lainnya.</p></div><div class="guide-actions"><div class="guide-action-list" aria-label="Pilih tombol aksi"><button v-for="item in guideActions" :key="item.id" type="button" :aria-pressed="action===item.id" :data-action="item.id" @click="action=item.id"><i aria-hidden="true"><BattleActionIcon :name="actionName(item.id)" /></i>{{ item.label }}</button></div><article class="guide-action-detail" :data-action="chosenAction.id" aria-live="polite"><BattleActionArtwork v-if="!['inspect','switch'].includes(chosenAction.id)" :action="actionName(chosenAction.id)" /><span>{{ chosenAction.cost }}</span><h4>{{ chosenAction.label }}</h4><p>{{ chosenAction.steps }}</p><small>{{ chosenAction.note }}</small></article></div></section>
  <section class="guide-turn-example" aria-labelledby="guide-example-title"><div><span class="guide-eyebrow">CONTOH SATU GILIRAN</span><h3 id="guide-example-title">Tiga AP, pikirkan giliran berikutnya.</h3><p>Ini latihan membaca AP. Klik setiap langkah; tidak ada aksi yang dikirim ke battle.</p></div><div class="guide-ap-readout"><strong>{{ exampleSteps[example].ap }}</strong><span>AP tersisa</span></div><div class="guide-example-steps" aria-label="Langkah contoh giliran"><button v-for="(item,index) in exampleSteps" :key="item.label" type="button" :aria-pressed="example===index" @click="example=index"><b>{{ item.badge }}</b>{{ item.label }}</button></div><p class="guide-example-text" aria-live="polite">{{ exampleSteps[example].text }}</p></section>
  <section class="guide-rules" aria-labelledby="guide-rules-title"><div class="guide-section-heading"><span class="guide-eyebrow">ATURAN DALAM BAHASA SEDERHANA</span><h3 id="guide-rules-title">Yang perlu kamu ingat.</h3><p>Pengaturan seperti AP, waktu, kapasitas slot, kuis, dan fitur tambahan dapat disesuaikan penyelenggara. Panduan ini menjelaskan TCG V1; mode Classic dapat berbeda.</p></div><details v-for="rule in guideRules" :key="rule.title"><summary>{{ rule.title }}</summary><p>{{ rule.text }}</p></details></section>
  <dialog ref="enlarged" class="guide-screen-dialog" :aria-label="`Layar ${tour.label} diperbesar`" @click="e=>{if(e.target===enlarged)enlarged.close()}"><header><strong>{{ tour.label }}</strong><button type="button" aria-label="Tutup gambar panduan" @click="enlarged.close()">Tutup ×</button></header><img :src="screen.src" :width="screen.width" :height="screen.height" :alt="`Layar ${tour.label} versi terbaru`"/><p>{{ tour.caption }} Data demo; nilai AP dan timer mengikuti pengaturan battle.</p></dialog>
  <footer class="guide-footer"><div><strong>Siap mencoba?</strong><p>Mulai dari pilih kartu, lihat AP, lalu satu aksi.</p></div><RouterLink to="/play">Masuk battle →</RouterLink></footer>
 </section>
</template>
